// review-policy: generated by scripts/build.mjs from src/. Do not edit.
// https://github.com/lightninglabs/review-policy

import { appendFileSync, readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

// ---- src/yaml.mjs ----
// A small, strict parser for the YAML subset that review-policy.yml uses.
//
// Supported: block mappings, block sequences of scalars or flow
// collections, flow sequences and flow mappings (which may span lines),
// single- and double-quoted strings, plain scalars, integers, booleans,
// null, and comments. Anything else (anchors, aliases, tags, block
// scalars, multiple documents, tabs, nested block mappings inside
// sequences) is rejected with an error rather than guessed at, so a
// config the parser does not fully understand fails closed.

export class YamlError extends Error {
  constructor(message, line) {
    super(line ? `line ${line}: ${message}` : message);
    this.name = 'YamlError';
  }
}

const RESERVED_START = new Set(['&', '*', '!', '|', '>', '%', '@', '`']);

// stripComment removes a trailing comment that is outside quotes. A '#'
// starts a comment only at the start of the line or after whitespace.
function stripComment(text, lineNo) {
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quote === '"') {
      if (c === '\\') i++;
      else if (c === '"') quote = null;
    } else if (quote === "'") {
      if (c === "'") {
        if (text[i + 1] === "'") i++;
        else quote = null;
      }
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === '#' && (i === 0 || text[i - 1] === ' ')) {
      return text.slice(0, i);
    }
  }
  if (quote) throw new YamlError('unterminated quoted string', lineNo);
  return text;
}

function flowDepthDelta(text) {
  let depth = 0;
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quote === '"') {
      if (c === '\\') i++;
      else if (c === '"') quote = null;
    } else if (quote === "'") {
      if (c === "'") {
        if (text[i + 1] === "'") i++;
        else quote = null;
      }
    } else if (c === '"' || c === "'") quote = c;
    else if (c === '[' || c === '{') depth++;
    else if (c === ']' || c === '}') depth--;
  }
  return depth;
}

// Cursor over a single scalar or flow value.
class FlowParser {
  constructor(text, lineNo) {
    this.s = text;
    this.i = 0;
    this.line = lineNo;
  }

  fail(msg) {
    throw new YamlError(msg, this.line);
  }

  ws() {
    while (this.i < this.s.length && /\s/.test(this.s[this.i])) this.i++;
  }

  peek() {
    return this.s[this.i];
  }

  done() {
    this.ws();
    return this.i >= this.s.length;
  }

  value(inFlow) {
    this.ws();
    const c = this.peek();
    if (c === '[') return this.seq();
    if (c === '{') return this.map();
    if (c === '"') return this.dquote();
    if (c === "'") return this.squote();
    return this.plain(inFlow, false);
  }

  seq() {
    this.i++;
    const out = [];
    this.ws();
    if (this.peek() === ']') {
      this.i++;
      return out;
    }
    for (;;) {
      out.push(this.value(true));
      this.ws();
      const c = this.peek();
      this.i++;
      if (c === ']') return out;
      if (c !== ',') this.fail("expected ',' or ']' in flow sequence");
      this.ws();
      // Allow a trailing comma.
      if (this.peek() === ']') {
        this.i++;
        return out;
      }
    }
  }

  map() {
    this.i++;
    const out = Object.create(null);
    this.ws();
    if (this.peek() === '}') {
      this.i++;
      return { ...out };
    }
    for (;;) {
      this.ws();
      const c = this.peek();
      let key;
      if (c === '"') key = this.dquote();
      else if (c === "'") key = this.squote();
      else key = this.plain(true, true);
      if (typeof key !== 'string') key = String(key);
      this.ws();
      if (this.peek() !== ':') this.fail(`expected ':' after key "${key}"`);
      this.i++;
      if (Object.hasOwn(out, key)) this.fail(`duplicate key "${key}"`);
      out[key] = this.value(true);
      this.ws();
      const d = this.peek();
      this.i++;
      if (d === '}') return { ...out };
      if (d !== ',') this.fail("expected ',' or '}' in flow mapping");
      this.ws();
      if (this.peek() === '}') {
        this.i++;
        return { ...out };
      }
    }
  }

  dquote() {
    this.i++;
    let out = '';
    const esc = { '"': '"', '\\': '\\', '/': '/', n: '\n', t: '\t', r: '\r', '0': '\0' };
    while (this.i < this.s.length) {
      const c = this.s[this.i++];
      if (c === '"') return out;
      if (c === '\\') {
        const e = this.s[this.i++];
        if (!(e in esc)) this.fail(`unsupported escape "\\${e}"`);
        out += esc[e];
      } else {
        out += c;
      }
    }
    this.fail('unterminated double-quoted string');
  }

  squote() {
    this.i++;
    let out = '';
    while (this.i < this.s.length) {
      const c = this.s[this.i++];
      if (c === "'") {
        if (this.s[this.i] === "'") {
          out += "'";
          this.i++;
        } else {
          return out;
        }
      } else {
        out += c;
      }
    }
    this.fail('unterminated single-quoted string');
  }

  plain(inFlow, isKey) {
    const start = this.i;
    const c = this.peek();
    if (c === undefined) return null;
    if (RESERVED_START.has(c)) {
      this.fail(`unsupported YAML syntax starting with "${c}" (quote the value)`);
    }
    if (c === ']' || c === '}' || c === ',') {
      if (inFlow) return null;
      this.fail(`unexpected "${c}"`);
    }
    if (c === '-' && (this.s[this.i + 1] === ' ' || this.s[this.i + 1] === undefined)) {
      this.fail('unexpected sequence item (block sequences must be on their own lines)');
    }
    while (this.i < this.s.length) {
      const ch = this.s[this.i];
      const next = this.s[this.i + 1];
      if (inFlow && (ch === ',' || ch === ']' || ch === '}' || ch === '[' || ch === '{')) break;
      if (ch === ':' && (next === undefined || next === ' ' || (inFlow && (next === ',' || next === '}' || next === ']')))) {
        if (isKey) break;
        this.fail('unexpected ": " in a plain value (quote the value)');
      }
      this.i++;
    }
    return scalar(this.s.slice(start, this.i).trim());
  }
}

function scalar(text) {
  if (text === '' || text === '~' || text === 'null') return null;
  if (text === 'true') return true;
  if (text === 'false') return false;
  if (/^-?\d+$/.test(text)) return Number(text);
  return text;
}

function parseInline(text, lineNo) {
  const p = new FlowParser(text, lineNo);
  const v = p.value(false);
  if (!p.done()) p.fail(`unexpected trailing text "${p.s.slice(p.i).trim()}"`);
  return v;
}

function parseKey(text, lineNo) {
  const t = text.trim();
  if (t === '') throw new YamlError('empty mapping key', lineNo);
  if (t[0] === '"' || t[0] === "'") {
    const p = new FlowParser(t, lineNo);
    const k = p.value(false);
    if (!p.done()) p.fail('unexpected text after quoted key');
    return k;
  }
  if (RESERVED_START.has(t[0]) || '[]{},?'.includes(t[0])) {
    throw new YamlError(`unsupported mapping key "${t}"`, lineNo);
  }
  return t;
}

// findKeyColon returns the index of the ':' that ends a mapping key, or -1.
function findKeyColon(text) {
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quote === '"') {
      if (c === '\\') i++;
      else if (c === '"') quote = null;
      continue;
    }
    if (quote === "'") {
      if (c === "'") quote = null;
      continue;
    }
    if ((c === '"' || c === "'") && i === 0) {
      quote = c;
      continue;
    }
    if ((c === '[' || c === '{') && i === 0) return -1;
    if (c === ':' && (i + 1 === text.length || text[i + 1] === ' ')) return i;
  }
  return -1;
}

// tokenize turns the text into logical lines, joining multi-line flow
// collections into one line.
function tokenize(src) {
  const raw = src.replace(/\r\n?/g, '\n').split('\n');
  const lines = [];
  for (let n = 0; n < raw.length; n++) {
    const lineNo = n + 1;
    let text = raw[n];
    const indentMatch = /^[ \t]*/.exec(text)[0];
    if (indentMatch.includes('\t')) throw new YamlError('tabs are not allowed for indentation', lineNo);
    text = stripComment(text, lineNo).replace(/\s+$/, '');
    if (text.trim() === '') continue;
    if (lines.length === 0 && text === '---') continue;
    if (/^(---|\.\.\.)(\s|$)/.test(text)) throw new YamlError('multiple documents are not supported', lineNo);
    let depth = flowDepthDelta(text);
    while (depth > 0) {
      n++;
      if (n >= raw.length) throw new YamlError('unterminated flow collection', lineNo);
      const more = stripComment(raw[n], n + 1).trim();
      text += ' ' + more;
      depth += flowDepthDelta(more);
    }
    if (depth < 0) throw new YamlError('unbalanced brackets', lineNo);
    lines.push({ indent: indentMatch.length, text: text.trim(), lineNo });
  }
  return lines;
}

export function parseYaml(src) {
  if (typeof src !== 'string') throw new YamlError('input must be a string');
  const lines = tokenize(src);
  if (lines.length === 0) return null;
  let pos = 0;

  function parseBlock(indent) {
    const first = lines[pos];
    if (first.text === '-' || first.text.startsWith('- ')) return parseSeq(first.indent);
    return parseMap(indent);
  }

  function parseSeq(indent) {
    const out = [];
    while (pos < lines.length) {
      const l = lines[pos];
      if (l.indent < indent) break;
      if (l.indent > indent) throw new YamlError('unexpected indentation', l.lineNo);
      if (!(l.text === '-' || l.text.startsWith('- '))) break;
      const rest = l.text.slice(1).trim();
      if (rest === '') throw new YamlError('empty or nested block sequence items are not supported', l.lineNo);
      if (findKeyColon(rest) !== -1) {
        throw new YamlError('mappings inside block sequences are not supported', l.lineNo);
      }
      out.push(parseInline(rest, l.lineNo));
      pos++;
    }
    return out;
  }

  function parseMap(indent) {
    const out = Object.create(null);
    while (pos < lines.length) {
      const l = lines[pos];
      if (l.indent < indent) break;
      if (l.indent > indent) throw new YamlError('unexpected indentation', l.lineNo);
      if (l.text === '-' || l.text.startsWith('- ')) {
        throw new YamlError('unexpected sequence item in a mapping', l.lineNo);
      }
      const colon = findKeyColon(l.text);
      if (colon === -1) throw new YamlError(`expected "key: value", got "${l.text}"`, l.lineNo);
      const key = parseKey(l.text.slice(0, colon), l.lineNo);
      if (Object.hasOwn(out, key)) throw new YamlError(`duplicate key "${key}"`, l.lineNo);
      const rest = l.text.slice(colon + 1).trim();
      pos++;
      if (rest !== '') {
        out[key] = parseInline(rest, l.lineNo);
        continue;
      }
      const next = lines[pos];
      const isSeqItem = next && (next.text === '-' || next.text.startsWith('- '));
      if (next && (next.indent > indent || (next.indent === indent && isSeqItem))) {
        out[key] = isSeqItem ? parseSeq(next.indent) : parseMap(next.indent);
      } else {
        out[key] = null;
      }
    }
    return { ...out };
  }

  const root = parseBlock(lines[0].indent);
  if (pos < lines.length) {
    throw new YamlError('unexpected content (check indentation)', lines[pos].lineNo);
  }
  return root;
}

// ---- src/glob.mjs ----
// Path globs for policy rules.
//
// Patterns are matched against the whole repository-relative path:
//   **   matches any number of path segments, including none
//   *    matches any run of characters within one segment
//   ?    matches one character within a segment
// Everything else is literal, and dot files get no special treatment.
// A pattern without a slash, like "go.mod", matches only at the root;
// write "**/go.mod" to match it anywhere.

const cache = new Map();

export function globToRegExp(pattern) {
  if (typeof pattern !== 'string' || pattern === '') {
    throw new Error('glob must be a non-empty string');
  }
  let re = '';
  const segs = pattern.split('/');
  for (let i = 0; i < segs.length; i++) {
    const seg = segs[i];
    const last = i === segs.length - 1;
    if (seg === '**') {
      // "a/**" matches everything under a; "**/b" and "a/**/b" match zero
      // or more directories in between.
      re += last ? '.*' : '(?:[^/]+/)*';
      continue;
    }
    if (seg.includes('**')) throw new Error(`"**" must be a whole path segment in "${pattern}"`);
    for (const ch of seg) {
      if (ch === '*') re += '[^/]*';
      else if (ch === '?') re += '[^/]';
      else re += ch.replace(/[.+^${}()|[\]\\]/g, '\\$&');
    }
    if (!last) re += '/';
  }
  return new RegExp(`^${re}$`);
}

export function matchGlob(pattern, path) {
  let re = cache.get(pattern);
  if (!re) {
    re = globToRegExp(pattern);
    cache.set(pattern, re);
  }
  return re.test(path);
}

export function matchAny(patterns, path) {
  return patterns.some((p) => matchGlob(p, path));
}

// ---- src/config.mjs ----
// Parsing and validation of .github/review-policy.yml.


export const CONFIG_PATH = '.github/review-policy.yml';
export const SEVERITIES = ['low', 'medium', 'high', 'critical'];

export class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigError';
  }
}

const isMap = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

function checkKeys(obj, allowed, where) {
  for (const k of Object.keys(obj)) {
    if (!allowed.includes(k)) throw new ConfigError(`unknown key "${k}" in ${where}`);
  }
}

function stringList(v, where, { globs = false } = {}) {
  if (v === undefined || v === null) return [];
  if (!Array.isArray(v)) throw new ConfigError(`${where} must be a list`);
  return v.map((s, i) => {
    if (typeof s !== 'string' || s === '') {
      throw new ConfigError(`${where}[${i}] must be a non-empty string`);
    }
    if (globs) {
      try {
        globToRegExp(s);
      } catch (err) {
        throw new ConfigError(`${where}[${i}]: ${err.message}`);
      }
    }
    return s;
  });
}

// validateConfig checks a parsed config object and returns a normalized
// copy. It throws ConfigError on anything unexpected, including unknown
// keys, so a typo cannot silently loosen the policy.
export function validateConfig(raw) {
  if (!isMap(raw)) throw new ConfigError('config must be a mapping');
  checkKeys(raw, ['version', 'bots', 'floor', 'never_auto_approve', 'tiers', 'experts'], 'config');
  if (raw.version !== 1) throw new ConfigError('version must be 1');

  const bots = stringList(raw.bots, 'bots');

  const floor = {};
  if (raw.floor !== undefined && raw.floor !== null) {
    if (!isMap(raw.floor)) throw new ConfigError('floor must be a mapping');
    checkKeys(raw.floor, SEVERITIES, 'floor');
    for (const sev of SEVERITIES) {
      floor[sev] = stringList(raw.floor[sev], `floor.${sev}`, { globs: true });
    }
  } else {
    for (const sev of SEVERITIES) floor[sev] = [];
  }

  const neverAutoApprove = stringList(raw.never_auto_approve, 'never_auto_approve', { globs: true });

  if (!isMap(raw.tiers)) throw new ConfigError('tiers must be a mapping');
  checkKeys(raw.tiers, SEVERITIES, 'tiers');
  const tiers = {};
  for (const sev of SEVERITIES) {
    const t = raw.tiers[sev];
    if (!isMap(t)) throw new ConfigError(`tiers.${sev} is required and must be a mapping`);
    checkKeys(t, ['humans', 'bot', 'fresh'], `tiers.${sev}`);
    if (!Number.isInteger(t.humans) || t.humans < 0) {
      throw new ConfigError(`tiers.${sev}.humans must be a non-negative integer`);
    }
    for (const flag of ['bot', 'fresh']) {
      if (t[flag] !== undefined && typeof t[flag] !== 'boolean') {
        throw new ConfigError(`tiers.${sev}.${flag} must be true or false`);
      }
    }
    tiers[sev] = { humans: t.humans, bot: t.bot === true, fresh: t.fresh === true };
  }

  const experts = {};
  if (raw.experts !== undefined && raw.experts !== null) {
    if (!isMap(raw.experts)) throw new ConfigError('experts must be a mapping');
    for (const [login, globs] of Object.entries(raw.experts)) {
      const key = login.toLowerCase();
      if (Object.hasOwn(experts, key)) throw new ConfigError(`duplicate expert "${login}"`);
      const list = stringList(globs, `experts.${login}`, { globs: true });
      if (list.length === 0) throw new ConfigError(`experts.${login} must list at least one glob`);
      experts[key] = list;
    }
  }

  return { version: 1, bots, floor, neverAutoApprove, tiers, experts };
}

export function parseConfig(text) {
  let raw;
  try {
    raw = parseYaml(text);
  } catch (err) {
    throw new ConfigError(`cannot parse YAML: ${err.message}`);
  }
  return validateConfig(raw);
}

// ---- src/policy.mjs ----
// Policy evaluation. Everything here is pure: no I/O, no clock, no
// environment. The same inputs always give the same verdict.


// The account the severity classifier workflow applies labels as.
export const CLASSIFIER = 'github-actions[bot]';

const LABEL_RE = /^severity-(low|medium|high|critical)$/;
const WRITE_PERMISSIONS = new Set(['admin', 'maintain', 'write']);
// Review states that do not change a reviewer's approval, as on GitHub.
const NEUTRAL_STATES = new Set(['COMMENTED', 'PENDING']);

const lc = (s) => String(s ?? '').toLowerCase();
const rank = (sev) => SEVERITIES.indexOf(sev);
const maxSeverity = (a, b) => (a === null ? b : b === null ? a : rank(a) >= rank(b) ? a : b);
const short = (sha) => String(sha ?? '').slice(0, 7);

export function hasWrite(permissions, login) {
  return WRITE_PERMISSIONS.has(permissions?.[lc(login)]);
}

// changedPaths returns every path the PR touches. A rename touches both
// its old and its new path.
export function changedPaths(files) {
  const out = new Set();
  for (const f of files ?? []) {
    if (typeof f === 'string') {
      out.add(f);
      continue;
    }
    if (f.filename) out.add(f.filename);
    if (f.previous_filename) out.add(f.previous_filename);
  }
  return [...out].sort();
}

// latestLabelers maps each severity label currently on the PR to the
// actor of its most recent "labeled" timeline event.
function latestLabelers(labels, timeline) {
  const current = new Set((labels ?? []).map(lc).filter((l) => LABEL_RE.test(l)));
  const actor = new Map();
  for (const ev of timeline ?? []) {
    const name = lc(ev.label);
    if (!current.has(name)) continue;
    if (ev.event === 'labeled') actor.set(name, ev.actor ?? null);
    else if (ev.event === 'unlabeled') actor.delete(name);
  }
  return [...current].sort().map((label) => ({ label, actor: actor.get(label) ?? null }));
}

// latestReviews keeps the most recent review per reviewer that changes
// its approval state. COMMENTED and PENDING reviews are skipped, as
// GitHub does.
function latestReviews(reviews) {
  const sorted = [...(reviews ?? [])].sort((a, b) => {
    const ta = a.submittedAt ?? '';
    const tb = b.submittedAt ?? '';
    if (ta !== tb) return ta < tb ? -1 : 1;
    return (a.id ?? 0) - (b.id ?? 0);
  });
  const latest = new Map();
  for (const r of sorted) {
    if (!r.user || NEUTRAL_STATES.has(r.state)) continue;
    latest.set(lc(r.user), r);
  }
  return [...latest.values()];
}

// actorsToCheck lists the logins whose repository permission the
// evaluation needs: severity labelers and approving reviewers that are
// not bots.
export function actorsToCheck(input) {
  const { config, labels, timeline, reviews, author } = input;
  const bots = new Set((config?.bots ?? []).map(lc));
  const out = new Set();
  for (const { actor } of latestLabelers(labels, timeline)) {
    if (actor && lc(actor) !== CLASSIFIER && lc(actor) !== lc(author)) out.add(lc(actor));
  }
  for (const r of latestReviews(reviews)) {
    const who = lc(r.user);
    if (r.state === 'APPROVED' && !bots.has(who) && who !== lc(author)) out.add(who);
  }
  return [...out].sort();
}

function fail(reason, details = {}, severity = null) {
  return { pass: false, severity, reason, details };
}

// evaluate decides whether a PR has the approvals its severity needs.
//
// input:
//   config       validated config (see config.mjs), or null
//   configError  why the config is missing or invalid, if it is
//   files        changed files: strings or {filename, previous_filename}
//   labels       names of the labels currently on the PR
//   timeline     label events, oldest first: {event, label, actor}
//   reviews      {id, user, state, commitId, submittedAt}
//   author       PR author login
//   headSha      the PR's current head commit
//   permissions  login (lower case) -> repository permission
//
// Returns {pass, severity, reason, details}.
export function evaluate(input) {
  const { config, configError, author, headSha, permissions = {} } = input;
  if (!config) {
    return fail(`invalid policy: ${configError || `${CONFIG_PATH} not found on the base branch`}`);
  }
  if (!headSha) return fail('no head commit');
  const listed = input.files?.length ?? 0;
  if (input.filesTotal != null && listed < input.filesTotal) {
    return fail(`cannot list every changed file (${listed} of ${input.filesTotal})`);
  }

  const bots = new Set(config.bots.map(lc));
  const authorLc = lc(author);
  const paths = changedPaths(input.files);
  const details = { headSha, author, paths: paths.length };

  // Severity from labels. A label counts only if the classifier or a
  // maintainer other than the author applied it most recently.
  const labelInfo = latestLabelers(input.labels, input.timeline).map(({ label, actor }) => {
    const sev = LABEL_RE.exec(label)[1];
    let why = null;
    if (!actor) why = 'no labeled event in the timeline';
    else if (lc(actor) === CLASSIFIER) why = null;
    else if (lc(actor) === authorLc) why = 'applied by the PR author';
    else if (!hasWrite(permissions, actor)) why = `applied by ${actor}, who lacks write access`;
    return { label, severity: sev, actor, counted: why === null, why };
  });
  details.labels = labelInfo;
  let labelSeverity = null;
  for (const l of labelInfo) if (l.counted) labelSeverity = maxSeverity(labelSeverity, l.severity);
  details.labelSeverity = labelSeverity;

  // Path floor.
  const configEdited = paths.includes(CONFIG_PATH);
  let floorSeverity = null;
  const floored = [];
  for (const p of paths) {
    let pf = p === CONFIG_PATH ? 'critical' : null;
    for (const sev of SEVERITIES) {
      if (matchAny(config.floor[sev], p)) pf = maxSeverity(pf, sev);
    }
    if (pf) {
      floored.push(p);
      floorSeverity = maxSeverity(floorSeverity, pf);
    }
  }
  details.floorSeverity = floorSeverity;
  details.flooredPaths = floored;
  details.configEdited = configEdited;

  if (!labelSeverity) {
    const ignored = labelInfo.filter((l) => !l.counted);
    const note = ignored.length
      ? ` (ignored: ${ignored.map((l) => `${l.label} ${l.why}`).join('; ')})`
      : '';
    return fail(`needs severity: no severity-* label applied by the classifier or a maintainer${note}`, details);
  }
  const severity = maxSeverity(labelSeverity, floorSeverity);
  const SEV = severity.toUpperCase();

  // Bot approvals are void if any path is never-auto-approve.
  const voidPaths = paths.filter((p) => p === CONFIG_PATH || matchAny(config.neverAutoApprove, p));
  details.botVoidPaths = voidPaths;

  // Expert author: every floored path must be inside their globs. The
  // PR must touch at least one floored path, and must not edit the
  // policy file.
  const expertGlobs = config.experts[authorLc];
  const expert =
    !!expertGlobs && !configEdited && floored.length > 0 && floored.every((p) => matchAny(expertGlobs, p));
  details.expert = expert;

  const tier = config.tiers[severity];
  const fresh = tier.fresh;
  const need = expert ? { humans: 0, bot: true } : { humans: tier.humans, bot: tier.bot };
  details.requirement = { ...need, fresh };

  // Approvals.
  const humans = [];
  const botApprovals = [];
  const ignored = [];
  for (const r of latestReviews(input.reviews)) {
    if (r.state !== 'APPROVED') continue;
    const who = r.user;
    const whoLc = lc(who);
    if (whoLc === authorLc) ignored.push({ login: who, why: 'PR author' });
    else if (fresh && r.commitId !== headSha) {
      ignored.push({ login: who, why: `approved ${short(r.commitId)}, not the head` });
    } else if (bots.has(whoLc)) {
      if (voidPaths.length) ignored.push({ login: who, why: 'bot approval void on never-auto-approve paths' });
      else botApprovals.push(who);
    } else if (!hasWrite(permissions, who)) ignored.push({ login: who, why: 'no write access' });
    else humans.push(who);
  }
  details.humanApprovals = humans;
  details.botApprovals = botApprovals;
  details.ignoredApprovals = ignored;

  const h = humans.length;
  const pass = h >= need.humans && (!need.bot || botApprovals.length > 0 || h >= need.humans + 1);

  const label = expert ? `${SEV} (expert author ${author})` : SEV;
  const where = fresh ? `on ${short(headSha)}` : `(head ${short(headSha)})`;
  const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
  let reason;
  if (!need.bot) {
    reason = `${label}: ${h} of ${plural(need.humans, 'human approval')} ${where}`;
  } else {
    const have = `${plural(h, 'human approval')}${botApprovals.length ? ' and the bot' : ''}`;
    if (pass) {
      reason = h === 0 ? `${label}: bot approval ${where}` : `${label}: ${have} ${where}`;
    } else {
      const want = need.humans
        ? `${plural(need.humans, 'human approval')} plus the bot or another human`
        : 'the bot or 1 human';
      const voidNote = voidPaths.length ? `; bot approval does not count for ${voidPaths[0]}` : '';
      reason = `${label}: needs ${want}, has ${have} ${where}${voidNote}`;
    }
  }
  return { pass, severity, reason, details };
}

// ---- src/github.mjs ----
// A minimal GitHub REST client built on fetch, with pagination.

export class GitHubError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'GitHubError';
    this.status = status;
  }
}

function nextLink(header) {
  if (!header) return null;
  for (const part of header.split(',')) {
    const m = /<([^>]+)>\s*;\s*rel="?next"?/.exec(part);
    if (m) return m[1];
  }
  return null;
}

export function createClient({ token, apiUrl = 'https://api.github.com', fetch = globalThis.fetch, maxPages = 100 }) {
  if (!token) throw new Error('a GitHub token is required');
  const base = apiUrl.replace(/\/+$/, '');

  async function raw(method, pathOrUrl, { query, body } = {}) {
    const url = new URL(pathOrUrl.startsWith('http') ? pathOrUrl : base + pathOrUrl);
    for (const [k, v] of Object.entries(query ?? {})) url.searchParams.set(k, String(v));
    const res = await fetch(url.toString(), {
      method,
      headers: {
        accept: 'application/vnd.github+json',
        authorization: `Bearer ${token}`,
        'x-github-api-version': '2022-11-28',
        'user-agent': 'review-policy',
        ...(body ? { 'content-type': 'application/json' } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    const text = await res.text();
    let data = null;
    if (text) {
      try {
        data = JSON.parse(text);
      } catch {
        data = text;
      }
    }
    if (!res.ok) {
      const msg = data && typeof data === 'object' && data.message ? data.message : text;
      throw new GitHubError(`${method} ${url.pathname}: ${res.status} ${msg}`, res.status);
    }
    return { data, link: res.headers.get('link') };
  }

  return {
    async request(method, path, opts) {
      return (await raw(method, path, opts)).data;
    },

    // paginate follows Link: rel="next" and concatenates the pages. For
    // endpoints that wrap the list in an object, pass the key.
    async paginate(path, { query = {}, key } = {}) {
      const out = [];
      let next = path;
      let opts = { query: { per_page: 100, ...query } };
      for (let page = 0; next; page++) {
        if (page >= maxPages) throw new GitHubError(`${path}: more than ${maxPages} pages`);
        const { data, link } = await raw('GET', next, opts);
        const items = key ? data?.[key] : data;
        if (!Array.isArray(items)) throw new GitHubError(`${path}: expected a list`);
        out.push(...items);
        next = nextLink(link);
        // Never send the token anywhere but the API.
        if (next && !next.startsWith(base + '/')) throw new GitHubError(`${path}: unexpected next link ${next}`);
        // The next link already carries the query string.
        opts = {};
      }
      return out;
    },
  };
}

// ---- src/main.mjs ----
// GitHub I/O: gather the inputs for a PR, evaluate, and write the check.


export const CHECK_NAME = 'review-policy';

// prNumbers works out which PRs an event is about.
export async function prNumbers(client, repo, eventName, event) {
  switch (eventName) {
    case 'pull_request_target':
    case 'pull_request':
    case 'pull_request_review':
      return [event.pull_request?.number].filter(Number.isInteger);
    case 'workflow_dispatch': {
      const v = String(event.inputs?.pr ?? '');
      if (!/^[1-9]\d*$/.test(v)) throw new Error('workflow_dispatch needs a numeric "pr" input');
      return [Number(v)];
    }
    case 'workflow_run': {
      // Fork PRs leave pull_requests empty, so also look the head commit
      // up among the open PRs. Each PR is then evaluated from the API, so
      // nothing in the triggering run is trusted.
      const run = event.workflow_run ?? {};
      const nums = new Set((run.pull_requests ?? []).map((p) => p.number).filter(Number.isInteger));
      if (run.head_sha) {
        const open = await client.paginate(`/repos/${repo}/pulls`, { query: { state: 'open' } });
        for (const p of open) if (p.head?.sha === run.head_sha) nums.add(p.number);
      }
      return [...nums].sort((a, b) => a - b);
    }
    default:
      throw new Error(`unsupported event "${eventName}"`);
  }
}

async function readConfig(client, repo, ref) {
  let data;
  try {
    data = await client.request('GET', `/repos/${repo}/contents/${CONFIG_PATH}`, { query: { ref } });
  } catch (err) {
    if (err.status === 404) return { configError: `${CONFIG_PATH} not found on ${ref}` };
    throw err;
  }
  if (data?.type !== 'file' || data.encoding !== 'base64' || typeof data.content !== 'string') {
    return { configError: `${CONFIG_PATH} on ${ref} is not a readable file` };
  }
  try {
    return { config: parseConfig(Buffer.from(data.content, 'base64').toString('utf8')) };
  } catch (err) {
    return { configError: `${CONFIG_PATH} on ${ref}: ${err.message}` };
  }
}

async function permission(client, repo, login) {
  try {
    const d = await client.request('GET', `/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
    return d?.role_name || d?.permission || 'none';
  } catch (err) {
    if (err.status === 404) return 'none';
    throw err;
  }
}

// gatherInputs reads everything evaluate() needs from the API. The
// config comes from the base branch, never from the PR.
export async function gatherInputs(client, repo, number) {
  const pr = await client.request('GET', `/repos/${repo}/pulls/${number}`);
  const [cfg, files, timeline, reviews] = await Promise.all([
    readConfig(client, repo, pr.base.ref),
    client.paginate(`/repos/${repo}/pulls/${number}/files`),
    client.paginate(`/repos/${repo}/issues/${number}/timeline`),
    client.paginate(`/repos/${repo}/pulls/${number}/reviews`),
  ]);
  const input = {
    ...cfg,
    files: files.map((f) => ({ filename: f.filename, previous_filename: f.previous_filename })),
    filesTotal: pr.changed_files,
    labels: (pr.labels ?? []).map((l) => l.name),
    timeline: timeline
      .filter((e) => e.event === 'labeled' || e.event === 'unlabeled')
      .map((e) => ({ event: e.event, label: e.label?.name, actor: e.actor?.login })),
    reviews: reviews.map((r) => ({
      id: r.id,
      user: r.user?.login,
      state: r.state,
      commitId: r.commit_id,
      submittedAt: r.submitted_at,
    })),
    author: pr.user?.login,
    headSha: pr.head.sha,
    permissions: {},
  };
  for (const login of actorsToCheck(input)) {
    input.permissions[login] = await permission(client, repo, login);
  }
  return input;
}

export function summarize(result) {
  const d = result.details ?? {};
  const lines = [`**${result.pass ? 'PASS' : 'FAIL'}:** ${result.reason}`, ''];
  const row = (k, v) => lines.push(`| ${k} | ${String(v).replace(/\|/g, '\\|').replace(/\n/g, ' ')} |`);
  lines.push('| | |', '| --- | --- |');
  if (d.headSha) row('Head', `\`${d.headSha}\``);
  if (d.author) row('Author', d.author);
  if (result.severity) row('Severity', result.severity.toUpperCase());
  if (d.labels) {
    row('Labels', d.labels.map((l) => `${l.label} by ${l.actor ?? '?'}${l.counted ? '' : ` (ignored: ${l.why})`}`).join('; ') || 'none');
  }
  if (d.floorSeverity) row('Path floor', `${d.floorSeverity.toUpperCase()}: ${d.flooredPaths.slice(0, 20).join(', ')}${d.flooredPaths.length > 20 ? ', …' : ''}`);
  if (d.configEdited) row('Policy file', `${CONFIG_PATH} changed: CRITICAL, bot approval void, no expert rule`);
  if (d.botVoidPaths?.length) row('Bot approval void', d.botVoidPaths.slice(0, 20).join(', '));
  if (d.expert !== undefined) row('Expert rule', d.expert ? 'applies' : 'does not apply');
  if (d.requirement) {
    const r = d.requirement;
    row('Needs', `${r.humans} human${r.humans === 1 ? '' : 's'}${r.bot ? ' + (bot or another human)' : ''}${r.fresh ? ', on the head commit' : ''}`);
  }
  if (d.humanApprovals) row('Human approvals', d.humanApprovals.join(', ') || 'none');
  if (d.botApprovals) row('Bot approvals', d.botApprovals.join(', ') || 'none');
  if (d.ignoredApprovals?.length) row('Ignored approvals', d.ignoredApprovals.map((i) => `${i.login} (${i.why})`).join('; '));
  return lines.join('\n').slice(0, 60000);
}

export async function writeCheck(client, repo, sha, result) {
  const body = {
    name: CHECK_NAME,
    head_sha: sha,
    status: 'completed',
    conclusion: result.pass ? 'success' : 'failure',
    completed_at: new Date().toISOString(),
    output: { title: result.reason.slice(0, 255), summary: summarize(result) },
  };
  const existing = await client.request('GET', `/repos/${repo}/commits/${sha}/check-runs`, {
    query: { check_name: CHECK_NAME, filter: 'latest', per_page: 100 },
  });
  const mine = (existing?.check_runs ?? []).find((c) => c.app?.slug === 'github-actions');
  if (mine) {
    const { name, head_sha, ...patch } = body;
    return client.request('PATCH', `/repos/${repo}/check-runs/${mine.id}`, { body: patch });
  }
  return client.request('POST', `/repos/${repo}/check-runs`, { body });
}

// run evaluates every PR the event refers to and writes one check run
// per PR head. It returns the results.
export async function run({ env = process.env, fetch = globalThis.fetch, log = console.log } = {}) {
  const repo = env.GITHUB_REPOSITORY;
  if (!repo || !/^[^/]+\/[^/]+$/.test(repo)) throw new Error('GITHUB_REPOSITORY is not set');
  const token = env.INPUT_TOKEN || env.GITHUB_TOKEN;
  const client = createClient({ token, apiUrl: env.GITHUB_API_URL || undefined, fetch });
  const event = JSON.parse(readFileSync(env.GITHUB_EVENT_PATH, 'utf8'));
  const numbers = await prNumbers(client, repo, env.GITHUB_EVENT_NAME, event);
  if (numbers.length === 0) log('review-policy: no pull request for this event');
  const results = [];
  for (const number of numbers) {
    const input = await gatherInputs(client, repo, number);
    const result = evaluate(input);
    await writeCheck(client, repo, input.headSha, result);
    log(`review-policy: #${number} ${result.pass ? 'PASS' : 'FAIL'}: ${result.reason}`);
    if (env.GITHUB_STEP_SUMMARY) {
      appendFileSync(env.GITHUB_STEP_SUMMARY, `### #${number}\n\n${summarize(result)}\n\n`);
    }
    results.push({ number, ...result });
  }
  return results;
}

// ---- src/cli.mjs ----
// Entry point: `node review-policy.mjs` in a workflow step.


export async function cli() {
  try {
    await run();
  } catch (err) {
    console.error(`::error::review-policy: ${err.message}`);
    process.exitCode = 1;
  }
}

const invoked = process.argv[1] && realpathSync(process.argv[1]);
if (invoked && invoked === realpathSync(fileURLToPath(import.meta.url))) await cli();
